/**
 * Official RRJA logo (supplied by the client, 2026-11-27).
 * Master file: /public/assets/rrja/logo/rrja-logo-original.png
 *
 * Two transparent variants are generated by scripts/build-logo-variants.mjs:
 *   color   - original colours, background removed          -> light backgrounds
 *   reverse - navy elements in white, orange/blue unchanged -> dark backgrounds
 * The reverse variant is a derived file and should be approved by RRJA.
 */
type Props = {
  variant?: 'color' | 'reverse'
  /** Tailwind height classes for the image (width follows the 3.05:1 aspect ratio) */
  sizeClass?: string
  className?: string
}

const RATIO = 1888 / 619
const HEIGHT = 48

export default function Logo({ variant = 'color', sizeClass = 'h-10 sm:h-12', className = '' }: Props) {
  const base = `/assets/rrja/logo/rrja-logo-${variant}`
  return (
    <img
      src={`${base}-96.webp`}
      srcSet={`${base}-96.webp 1x, ${base}-192.webp 2x`}
      alt="RRJA Customs Brokerage Services"
      width={Math.round(HEIGHT * RATIO)}
      height={HEIGHT}
      className={`${sizeClass} w-auto ${className}`}
      decoding="async"
    />
  )
}
